mapper.select:
SELECT t.id, t.school_id AS schoolId, t.user_id AS userId, t.teacher_no AS teacherNo, t.teacher_name AS teacherName, t.gender, t.phone, t.id_card AS idCard, t.school_stage AS schoolStage, t.position_name AS positionName, t.employee_status AS employeeStatus, t.register_status AS registerStatus, u.status AS status, t.is_head_teacher AS isHeadTeacher, t.avatar_file_id AS avatarFileId, u.logo_url AS imgUrl, ec.class_name, eg.grade_name FROM t_as_teacher t LEFT JOIN t_base_user u ON t.user_id = u.id AND u.is_valid = 1 LEFT JOIN t_as_teacher_class tc ON tc.teacher_id = t.id AND tc.is_valid = 1 LEFT JOIN t_educl_class ec ON ec.id = tc.class_id AND ec.is_valid = 1 LEFT JOIN t_educl_grade eg ON eg.id = ec.grade_id AND eg.is_valid = 1
t.is_valid = 1
AND t.school_id = #{query.schoolId}
AND t.teacher_name LIKE CONCAT('%', #{query.teacherName}, '%')
AND t.phone LIKE CONCAT('%', #{query.phone}, '%')
AND t.school_stage = #{query.schoolStage}
AND t.employee_status = #{query.employeeStatus}
AND t.register_status = #{query.registerStatus} AND u.approve_status = #{query.userStatus}
AND t.register_status = #{query.registerStatus}
AND EXISTS ( SELECT 1 FROM t_teacher_subject ts WHERE ts.teacher_id = t.id AND ts.subject_id = #{query.subjectId} AND ts.is_valid = 1 )
GROUP BY t.id ORDER BY t.school_id DESC, t.teacher_name ASC

SELECT cc.id AS courseClassId, cc.course_class_name AS courseClassName, stu.class_id AS classId, stu.student_name AS studentName, stu.student_no AS studentNo, CONCAT(IFNULL(g.grade_name, ''), IFNULL(c.class_name, '')) AS gradeClassName FROM t_as_course_class cc INNER JOIN t_as_enrollment e ON e.course_class_id = cc.id AND e.is_valid = 1 AND e.enroll_status IN (1, 3) INNER JOIN t_as_student stu ON stu.id = e.student_id AND stu.is_valid = 1 AND stu.register_status = 1 LEFT JOIN t_educl_class c ON c.id = stu.class_id AND c.is_valid = 1 LEFT JOIN t_educl_grade g ON g.id = stu.grade_id AND g.is_valid = 1 WHERE cc.is_valid = 1 AND cc.teacher_id = #{query.teacherId} AND cc.school_id = #{query.schoolId}
AND (stu.student_name LIKE CONCAT('%', #{query.keyword}, '%') OR stu.student_no LIKE CONCAT('%', #{query.keyword}, '%'))
GROUP BY stu.id,cc.id ORDER BY stu.student_no ASC
